package local.skyfamily;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import android.util.JsonWriter;import org.json.*;import java.io.*;import java.util.*;
final class SchoolDb extends SQLiteOpenHelper {
 private static SchoolDb instance;static synchronized SchoolDb get(Context c){if(instance==null)instance=new SchoolDb(c.getApplicationContext());return instance;}private SchoolDb(Context c){super(c,"school.sqlite",null,1);setWriteAheadLoggingEnabled(true);}
 public void onConfigure(SQLiteDatabase db){db.setForeignKeyConstraintsEnabled(true);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE notebooks(id TEXT PRIMARY KEY,name TEXT NOT NULL)");d.execSQL("INSERT INTO notebooks VALUES('general','General schoolwork')");d.execSQL("CREATE TABLE pages(id TEXT PRIMARY KEY,notebook TEXT NOT NULL REFERENCES notebooks(id) ON DELETE CASCADE,section TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,ink TEXT NOT NULL,refs TEXT NOT NULL,updated INTEGER NOT NULL)");d.execSQL("CREATE TABLE tasks(id TEXT PRIMARY KEY,notebook TEXT NOT NULL REFERENCES notebooks(id) ON DELETE CASCADE,title TEXT NOT NULL,detail TEXT NOT NULL,due TEXT NOT NULL,important INTEGER NOT NULL,done INTEGER NOT NULL)");}
 public void onUpgrade(SQLiteDatabase d,int old,int next){throw new IllegalStateException("School database migration required; data not deleted");}
 JSONArray rows(String sql,String... args){JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery(sql,args)){while(c.moveToNext()){JSONObject o=new JSONObject();for(int i=0;i<c.getColumnCount();i++)try{o.put(c.getColumnName(i),c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));}catch(Exception e){throw new IllegalStateException(e);}a.put(o);}}return a;}
 JSONObject one(String table,String id){return rows("SELECT * FROM "+table+" WHERE id=?",id).optJSONObject(0);}
 void exec(String sql,Object... args){getWritableDatabase().execSQL(sql,args);}
 void limit(String table,int max){if(rows("SELECT count(*) AS n FROM "+table).optJSONObject(0).optInt("n")>=max)throw new IllegalStateException("School "+table+" limit reached ("+max+")");}
 String notebook(String name){limit("notebooks",50);String id=UUID.randomUUID().toString();exec("INSERT INTO notebooks VALUES(?,?)",id,name);return id;}
 String page(String notebook){limit("pages",500);String id=UUID.randomUUID().toString();exec("INSERT INTO pages VALUES(?,?,?,?,?,?,?,?)",id,notebook,"Notes","Untitled page","","[]","[]",System.currentTimeMillis());return id;}
 void export(OutputStream stream)throws Exception{SQLiteDatabase d=getReadableDatabase();d.beginTransactionNonExclusive();try(JsonWriter w=new JsonWriter(new OutputStreamWriter(stream,"UTF-8"))){w.beginObject().name("format").value("SkyFamilySchool").name("schema").value(1);for(String table:new String[]{"notebooks","pages","tasks"}){w.name(table).beginArray();try(Cursor c=d.rawQuery("SELECT * FROM "+table,null)){while(c.moveToNext()){if(Thread.currentThread().isInterrupted())throw new IOException("Export interrupted");w.beginObject();for(int i=0;i<c.getColumnCount();i++){w.name(c.getColumnName(i));if(c.getType(i)==Cursor.FIELD_TYPE_INTEGER)w.value(c.getLong(i));else w.value(c.getString(i));}w.endObject();}}w.endArray();}w.endObject();w.flush();d.setTransactionSuccessful();}finally{d.endTransaction();}}
}
